import { describe, expect, it } from 'vitest'
import { lexSymbols, quote, stripComment } from './symbols'

// Every string of length 1..3 over an alphabet that covers the syntax characters.
const ALPHABET = ['a', 'E', "'", '"', ' ', '#', '|', '-', '>', 'ε', '→', ':', '=']
function* strings(max: number): Generator<string> {
  let level = ['']
  for (let n = 1; n <= max; n++) {
    level = level.flatMap((s) => ALPHABET.map((c) => s + c))
    yield* level
  }
}

describe('lexSymbols', () => {
  it('splits on whitespace and keeps the content of quoted symbols', () => {
    expect(lexSymbols(`a  'b c' "d'e" E'`)).toMatchObject([
      { text: 'a', quoted: false },
      { text: 'b c', quoted: true },
      { text: "d'e", quoted: true },
      { text: "E'", quoted: false },
    ])
  })

  it('treats a lone quote without a closing pair as a plain symbol', () => {
    expect(lexSymbols(`' x`).map((t) => t.text)).toEqual(["'", 'x'])
  })
})

describe('stripComment', () => {
  it('cuts an unquoted # symbol and the rest of the line', () => {
    expect(stripComment('A -> x y  # note')).toBe('A -> x y  ')
  })

  it("keeps a quoted '#' and a # inside a symbol", () => {
    expect(stripComment("A -> '#' a#b")).toBe("A -> '#' a#b")
  })
})

describe('quote', () => {
  it('leaves ordinary symbols alone, including ones with a quote inside', () => {
    expect(quote('id')).toBe('id')
    expect(quote("E'")).toBe("E'")
    expect(quote('(')).toBe('(')
  })

  it('quotes symbols that would be read as syntax', () => {
    expect(quote('|')).toBe("'|'")
    expect(quote('#')).toBe("'#'")
    expect(quote('ε')).toBe("'ε'")
    expect(quote('->')).toBe("'->'")
    expect(quote('a b')).toBe("'a b'")
    expect(quote("it's x")).toBe(`"it's x"`)
  })

  it('round-trips: lex(quote(s)) is [s] for every symbol without both quote kinds', () => {
    const failures: string[] = []
    for (const s of strings(3)) {
      if (s.includes("'") && s.includes('"')) continue
      const toks = lexSymbols(stripComment(quote(s)))
      if (toks.length !== 1 || toks[0].text !== s) failures.push(JSON.stringify(s))
    }
    expect(failures).toEqual([])
  })
})
